create function pg_temp.save_evidence(cid uuid, eid uuid, predecessor uuid default null)
returns uuid language plpgsql security invoker as $$
declare path text := 'documents/cases/' || cid || '/' || eid || '/synthetic.pdf';
begin
  insert into storage.objects(bucket_id,name,owner_id) values ('documents',path,auth.uid()::text);
  return public.register_case_evidence(eid,cid,'survey_plan_copy','Synthetic survey document',path,'synthetic.pdf','application/pdf',100,predecessor);
end; $$;
